#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.7 Pro Terminal - Complete Zero-Km Installer
# Can be run on a brand-new server OR safely upgrade an existing one!
# Optional CLI Migration:
#   bash install_kaviancrypto_v7_7.sh /path/to/backup.zip|.json
#
# Updates in v7.7:
#   - Market Cap Rank Everywhere in Telegram & Panel:
#       * Cached 6-hour Multi-Provider Market Cap Rank Engine
#         (CoinGecko primary + CoinPaprika & CoinCap automatic fallbacks
#         + Binance 1000x/renamed symbol alias mapping)
#       * Works even when Top MarketCap Filter = 0 (All Coins)
#       * Displayed in ALL Telegram LONG & SHORT Signal Posts
#       * Displayed in ALL TP1 / TP2 / TP3 / SL / BE / Trailed SL Replies
#         (auto-backfills older pre-v7.7 open trades too!)
#       * Displayed in Manual Exit & Manual Live Visual Snapshot Reports
#       * Displayed per coin in Weekly (7D) & Monthly (30D) P&L Reports
#       * Saved inside active_trades.json & included in Full-State Backups
# + Unified Auto Full-State Backup to Telegram (.zip / .json + SHA-256)
# + Weekly/Monthly P&L Reports + 31-Day Auto-Archive Retention
# + Split Check TP/SL Now & Visual TP/SL Report + Working Manual Exit
# + Strategy Studio Pro (Per-Strategy Parameters Menu + Presets +
#   Multi-TF Matrix + 500-Bar Walk-Forward Backtester)
# + Unified Obsidian Gold Pro Palette (Obsidian & Bento HUD)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"
RESTORE_ARG="${1:-}"

echo "========================================================"
echo "  kaviancrypto v7.7 Pro - Complete Zero-Km Installer"
echo "  Market Cap Rank in All Signals & Reports + Full Backup"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR" "$APP_DIR/backups"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_7.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_7.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_7.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v7.7 core files ==="
